/// Bundled CPU doodles for v2.0 single-player (`app/assets/cpu/manifest_v2.json`,
/// generated by `tool/gen_cpu_doodles.dart` from the real analyser) and how
/// a stage turns one into a fighter. CPU characters are derived exactly like
/// players' characters (same quantised features → same [Genome]).
library;

import 'battle_v3/battle_v3.dart';

/// Asset key / repo path (relative to `app/`) of the v2 manifest.
const String kCpuManifestV2Path = 'assets/cpu/manifest_v2.json';

/// One bundled CPU doodle.
class CpuCharacterV2 {
  const CpuCharacterV2({
    required this.id,
    required this.name,
    required this.asset,
    required this.features,
    required this.energy10,
    required this.skill10,
    required this.imageHash,
    this.shape = '',
  });

  final String id;

  /// Kid-facing name (kana).
  final String name;

  /// Asset key of the cut-out PNG.
  final String asset;
  final FeatureVector features;
  final int energy10;
  final int skill10;
  final String imageHash;

  /// Generator hint for the Puppet team: `limbs`, `blob` or `vehicle`.
  final String shape;

  Genome genome([V3Spec s = const V3Spec()]) => Genome.derive(
    s,
    features: features,
    energy10: energy10,
    skill10: skill10,
    imageHash: imageHash,
  );

  factory CpuCharacterV2.fromJson(Map<String, Object?> j) => CpuCharacterV2(
    id: j['id']! as String,
    name: j['name']! as String,
    asset: j['asset']! as String,
    features: FeatureVector.tryParse(j['features'])!,
    energy10: j['energy10']! as int,
    skill10: j['skill10']! as int,
    imageHash: j['imageHash']! as String,
    shape: j['shape'] as String? ?? '',
  );
}

class CpuRosterV2 {
  CpuRosterV2(Iterable<CpuCharacterV2> characters)
    : byId = {for (final c in characters) c.id: c};

  final Map<String, CpuCharacterV2> byId;

  Iterable<CpuCharacterV2> get characters => byId.values;

  factory CpuRosterV2.fromManifestJson(Map<String, Object?> manifest) =>
      CpuRosterV2([
        for (final c in manifest['characters']! as List)
          CpuCharacterV2.fromJson((c as Map).cast<String, Object?>()),
      ]);

  /// The CPU fighter of [stage]: the stage's doodle at the CPU level, stats
  /// scaled by the stage's power %, offline moves.
  FighterSetup stageFighter(Stage stage, {V3Spec s = const V3Spec()}) {
    final c = byId[stage.cpuId];
    if (c == null) throw ArgumentError('unknown CPU ${stage.cpuId}');
    return setupAt(
      s,
      c.genome(s),
      stage.cpuLevel,
      powerPct: stage.cpuPowerPct,
      label: c.name,
    );
  }
}
